import json
# Build the 30x30 input from the visible periodic tile pattern.
a=[[0]*30 for _ in range(30)]
vals=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for tr in range(4):
  for tc in range(4):
    r0=1+7*tr; c0=1+7*tc
    for r in range(5):
      for c in range(5):
        a[r0+r][c0+c]=4
    for r in range(1,4):
      for c in range(1,4):
        a[r0+r][c0+c]=vals[tr][tc]
# Join aligned occurrences of the non-dominant core colors across separator corridors.
for color in (3,8):
  # horizontal pairs sharing tile row; fill all blank separator stripes between their cores
  for tr in range(4):
    cols=[tc for tc in range(4) if vals[tr][tc]==color]
    for i,ta in enumerate(cols):
      for tb in cols[i+1:]:
        if tb-ta<2: continue
        r0=1+7*tr
        for rr in range(r0+1,r0+4):
          for tc in range(ta,tb):
            # separator after tile tc (columns 6-7 offset from initial grid)
            for cc in range(1+7*tc+5,1+7*(tc+1)):
              a[rr][cc]=color
  # vertical pairs sharing tile column
  for tc in range(4):
    rows=[tr for tr in range(4) if vals[tr][tc]==color]
    for i,ta in enumerate(rows):
      for tb in rows[i+1:]:
        if tb-ta<2: continue
        c0=1+7*tc
        for cc in range(c0+1,c0+4):
          for tr in range(ta,tb):
            for rr in range(1+7*tr+5,1+7*(tr+1)):
              a[rr][cc]=color
print(json.dumps(a))

